// Find all text containing "Something went wrong" and their parent context
const elements = document.querySelectorAll('*');
const results = [];
for (const el of elements) {
  if (el.textContent && el.textContent.includes('Something went wrong') && el.children.length === 0) {
    let parent = el.closest('[class*="card"], [class*="project"], [class*="Card"], [class*="Project"]');
    results.push({
      tag: el.tagName,
      text: el.textContent.substring(0, 100),
      parentClass: parent ? parent.className : 'none',
      parentText: parent ? parent.textContent.substring(0, 200) : 'none'
    });
  }
}
return JSON.stringify(results, null, 2);

// Find the error boundary element and its context
const els = document.querySelectorAll('*');
for (const el of els) {
  if (el.textContent === 'Something went wrong' && el.children.length === 0) {
    // Walk up to find context
    let parents = [];
    let current = el;
    for (let i = 0; i < 10; i++) {
      current = current.parentElement;
      if (!current) break;
      parents.push({
        tag: current.tagName,
        class: current.className.substring(0, 80),
        id: current.id,
        dataAttrs: Array.from(current.attributes).filter(a => a.name.startsWith('data-')).map(a => `${a.name}=${a.value}`).join(', '),
        siblingText: Array.from(current.children).map(c => c.textContent.substring(0, 60)).join(' | ')
      });
    }
    return JSON.stringify(parents, null, 2);
  }
}
return 'not found';

// Let's check the project data to see what's different about "Data Pipeline"
// Look for the card content of Data Pipeline vs a working card
const els = document.querySelectorAll('*');
const cards = [];
for (const el of els) {
  const text = el.textContent;
  if (text && text.includes('Owner:') && el.children.length > 0) {
    // Check if this looks like a card
    const hasRevenue = text.includes('Revenue:');
    const hasUsers = text.includes('Users:');
    const hasError = text.includes('Something went wrong');
    const cardText = el.textContent.substring(0, 200);

    // Only get leaf-ish cards
    if (cardText.split('Owner:').length === 2) {
      cards.push({
        text: cardText,
        hasRevenue,
        hasUsers,
        hasError
      });
    }
  }
}
return JSON.stringify(cards, null, 2);

