// Try to access React fiber to see the props for the Data Pipeline card
const els = document.querySelectorAll('*');
for (const el of els) {
  if (el.textContent && el.textContent.startsWith('Data Pipeline') && el.textContent.includes('Frank')) {
    // Find React fiber
    const fiberKey = Object.keys(el).find(k => k.startsWith('__reactFiber'));
    if (fiberKey) {
      let fiber = el[fiberKey];
      // Walk up to find the component with project data
      let props = [];
      let current = fiber;
      for (let i = 0; i < 20; i++) {
        if (!current) break;
        if (current.memoizedProps && typeof current.memoizedProps === 'object') {
          const p = current.memoizedProps;
          if (p.project || p.stats || p.data) {
            props.push({
              type: current.type?.name || current.type || 'unknown',
              project: p.project,
              stats: p.stats,
              data: p.data
            });
          }
        }
        current = current.return;
      }
      return JSON.stringify(props, null, 2);
    }
    return 'no fiber found';
  }
}
return 'element not found';

// Check all project cards' props to compare
const els = document.querySelectorAll('*');
const results = [];
for (const el of els) {
  const fiberKey = Object.keys(el).find(k => k.startsWith('__reactFiber'));
  if (fiberKey) {
    let fiber = el[fiberKey];
    if (fiber.type && (fiber.type.name === 'ProjectCard' || fiber.type === 'ProjectCard')) {
      const p = fiber.memoizedProps;
      results.push({
        name: p.project?.name,
        id: p.project?.id,
        stats: p.stats
      });
    }
  }
}
return JSON.stringify(results, null, 2);

// Walk the fiber tree from root to find all ProjectCard instances
const rootEl = document.getElementById('root');
const fiberKey = Object.keys(rootEl).find(k => k.startsWith('__reactFiber'));
const rootFiber = rootEl[fiberKey];

const cards = [];
function walkFiber(fiber) {
  if (!fiber) return;
  if (fiber.type && typeof fiber.type === 'function' && fiber.type.name === 'ProjectCard') {
    const p = fiber.memoizedProps;
    cards.push({
      name: p.project?.name,
      id: p.project?.id,
      statsIsNull: p.stats === null,
      statsIsUndefined: p.stats === undefined,
      stats: p.stats
    });
  }
  walkFiber(fiber.child);
  walkFiber(fiber.sibling);
}
walkFiber(rootFiber);
return JSON.stringify(cards, null, 2);

// Try finding the parent component that manages project data
const rootEl = document.getElementById('root');
const fiberKey = Object.keys(rootEl).find(k => k.startsWith('__reactFiber'));
const rootFiber = rootEl[fiberKey];

const stateComponents = [];
function walkFiber(fiber) {
  if (!fiber) return;
  if (fiber.memoizedState && fiber.type && typeof fiber.type === 'function') {
    const name = fiber.type.name;
    if (name && !name.startsWith('_') && name !== 'ErrorBoundary') {
      // Check if state contains projects
      let state = fiber.memoizedState;
      while (state) {
        if (state.memoizedState && Array.isArray(state.memoizedState) && state.memoizedState.length > 0) {
          const first = state.memoizedState[0];
          if (first && first.name && first.owner) {
            stateComponents.push({
              component: name,
              projectCount: state.memoizedState.length,
              projects: state.memoizedState.map(p => ({name: p.name, hasStats: !!p.stats, stats: p.stats}))
            });
          }
        }
        state = state.next;
      }
    }
  }
  walkFiber(fiber.child);
  walkFiber(fiber.sibling);
}
walkFiber(rootFiber);
return JSON.stringify(stateComponents, null, 2);
